#!/usr/bin/env python3
"""Bundle the isolated UI without HTTP, require(), loadstring(), or Studio assets."""
import argparse
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "src/violent"
OUTPUT = ROOT / "src/ViolentStandalone.luau"
MODULES = ("Theme", "Features", "Core", "Controls", "Preview", "Window")


def bundle():
    parts = [
        "-- GENERATED by python3 tools/build_violent.py; edit src/violent instead.\n"
        "-- Standalone client UI replica. No HTTP, dependencies, or gameplay logic.\n"
        "-- Execute this ENTIRE file in a live Roblox client. RightShift toggles UI.\n"
        "local factories, cache = {}, {}\n"
        "local function import(name)\n"
        "    if cache[name] == nil then\n"
        "        local factory = assert(factories[name], 'Unknown UI module: ' .. name)\n"
        "        cache[name] = factory(import)\n"
        "    end\n"
        "    return cache[name]\n"
        "end\n"
    ]
    for name in MODULES:
        content = (SOURCE / "modules" / f"{name}.luau").read_text(encoding="utf-8")
        parts.append(f'\n-- Module: {name}\nfactories["{name}"] = function(import)\n{content}end\n')
    parts.append('\n-- Entry point\n' + (SOURCE / 'Main.luau').read_text(encoding='utf-8'))
    return ''.join(parts)


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    expected = bundle()
    if args.check:
        if not OUTPUT.exists() or OUTPUT.read_text(encoding='utf-8') != expected:
            raise SystemExit('Standalone bundle is stale; run python3 tools/build_violent.py')
        print('PASS standalone UI bundle is current')
    else:
        OUTPUT.write_text(expected, encoding='utf-8')
        print(f'Wrote {OUTPUT.relative_to(ROOT)} ({len(expected.encode()):,} bytes)')
